// features/vendor-lifecycle.feature: A re-uploaded document is the one that gets reviewed
import { expect, expectStatus, test } from "../../fixtures";
import type { Document } from "../../fixtures";

test("a re-uploaded w9 is the one that gets reviewed", { tag: "@LIF-01" }, async ({ factory, apiAs }) => {
  // Arrange: a draft vendor with extracted insurance certificate and contract
  const member = await apiAs("member");
  const vendor = await factory.vendor();
  await factory.upload(vendor.id, "insurance_certificate");
  await factory.upload(vendor.id, "contract");

  // Arrange: a first w9 whose legal name is "First Name LLC", extracted
  const firstW9 = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9-first.txt",
          mimeType: "text/plain",
          buffer: Buffer.from("Legal Name: First Name LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n"),
        },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () => (await expectStatus<Document>(await member.get(`/api/documents/${firstW9.id}`), 200)).status,
      { message: "first w9 is extracted", timeout: 30_000 },
    )
    .toBe("extracted");

  // Arrange: a second w9 whose legal name is "Second Name LLC", extracted
  const secondW9 = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9-second.txt",
          mimeType: "text/plain",
          buffer: Buffer.from("Legal Name: Second Name LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n"),
        },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () => {
        const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return docs.map((d) => d.status);
      },
      { message: "all four documents are extracted", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted", "extracted"]);

  // Act: the member submits and a reviewer opens the review queue
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const reviewer = await apiAs("reviewer");
  const queue = await expectStatus<
    { vendor_id: string; extractions: { document_id: string; kind: string; fields: Record<string, { value: string | null }> }[] }[]
  >(await reviewer.get("/api/review-queue"), 200);

  // Assert: the queue's w9 extraction shows the second upload's legal name
  const item = queue.find((i) => i.vendor_id === vendor.id);
  expect(item, `vendor ${vendor.id} is in the review queue`).toBeDefined();
  const w9Extractions = (item?.extractions ?? []).filter((e) => e.kind === "w9");
  expect(w9Extractions, "exactly one w9 extraction awaits review").toHaveLength(1);
  expect(w9Extractions[0]?.document_id).toBe(secondW9.id);
  expect(w9Extractions[0]?.fields.legal_name?.value).toBe("Second Name LLC");

  // Assert: the vendor's documents list both w9 uploads, oldest first
  const documents = await expectStatus<(Document & { created_at: string; filename: string })[]>(
    await member.get(`/api/vendors/${vendor.id}/documents`),
    200,
  );
  expect(documents.filter((d) => d.kind === "w9").map((d) => d.id)).toEqual([firstW9.id, secondW9.id]);
  expect(documents.filter((d) => d.kind === "w9").map((d) => d.filename)).toEqual(["w9-first.txt", "w9-second.txt"]);
  const createdAt = documents.map((d) => Date.parse(d.created_at));
  expect(createdAt, "documents are listed oldest first").toEqual([...createdAt].sort((a, b) => a - b));
});
